/*
    Dashboard Tổng hợp — DASH_MainSummary_GetData
    KPI trang Tổng quan hệ thống (/bang-dieu-khien.html).
    Biểu đồ chi tiết load riêng qua HomeDashboardApi (SP module từng mục).

    Lọc Khoa / Khóa / Lớp / Từ ngày–Đến ngày — chuẩn DASH_StudentClassSize_GetData
    (loại trừ SV kỷ luật / tốt nghiệp trong khoảng ngày khỏi StudyQuantity).

    @YearID, @Semester — tuỳ chọn (giữ cho cảnh báo Overview)
    @ScienceID, @CourseID, @ClassID — tuỳ chọn, danh sách ID cách nhau bởi dấu phẩy
    @FromDate, @ToDate — tuỳ chọn; mặc định tháng hiện tại
    @ResultSet: 1 = KPI tổng quan; 2 = cảnh báo; NULL = cả hai
*/

IF OBJECT_ID(N'dbo.DASH_MainSummary_GetData', N'P') IS NOT NULL
    DROP PROCEDURE dbo.DASH_MainSummary_GetData;
GO

CREATE PROCEDURE dbo.DASH_MainSummary_GetData
(
    @YearID int = NULL,
    @Semester tinyint = NULL,
    @ScienceID nvarchar(1000) = NULL,
    @CourseID nvarchar(1000) = NULL,
    @ClassID nvarchar(1000) = NULL,
    @FromDate datetime = NULL,
    @ToDate datetime = NULL,
    @ResultSet tinyint = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Mặc định: tháng hiện tại nếu không truyền ngày (chuẩn Sĩ số lớp)
    IF @FromDate IS NULL
        SET @FromDate = DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()), 0);

    IF @ToDate IS NULL
        SET @ToDate = DATEADD(DAY, -1, DATEADD(MONTH, 1, DATEADD(MONTH, DATEDIFF(MONTH, 0, GETDATE()), 0)));

    -- Đảm bảo @ToDate bao gồm cả ngày cuối (đến 23:59:59)
    SET @ToDate = DATEADD(DAY, 1, @ToDate);
    SET @ToDate = DATEADD(SECOND, -1, @ToDate);

    Create Table #tblMetrics
    (
        SectionGroup nvarchar(50),
        SectionTitle nvarchar(200),
        MetricKey nvarchar(80),
        MetricLabel nvarchar(200),
        MetricValue nvarchar(100),
        MetricNote nvarchar(500),
        ColorClass nvarchar(30),
        SortOrder int
    );

    Select
        SIM_Class.ClassID,
        SIM_Class.ClassName,
        SIM_Class.ScienceID,
        SIM_Science.ScienceName,
        SIM_Class.CourseID,
        SIM_Course.CourseName,
        ISNULL(tblStudent.TotalStudent, 0) as NowStudentCount,
        -- StudyQuantity = Tổng SV - SV kỷ luật trong kỳ - SV tốt nghiệp trong kỳ
        Case
            When ISNULL(tblStudent.TotalStudent, 0)
                - ISNULL(tblStudent.WarningQuantity, 0)
                - ISNULL(tblStudent.GraduationInPeriod, 0) < 0
            Then 0
            Else ISNULL(tblStudent.TotalStudent, 0)
                - ISNULL(tblStudent.WarningQuantity, 0)
                - ISNULL(tblStudent.GraduationInPeriod, 0)
        End as StudyQuantity,
        ISNULL(tblStudent.GraduationQuantity, 0) as GraduationQuantity,
        ISNULL(tblStudent.WarningQuantity, 0) as WarningQuantity
    Into #tblClassData
    From SIM_Class
        Inner Join SIM_Course On SIM_Course.CourseID = SIM_Class.CourseID
        Inner Join SIM_Science On SIM_Science.ScienceID = SIM_Class.ScienceID
        Inner Join
        (
            Select
                SIM_Student.ClassID,
                Count(*) as TotalStudent,
                -- WarningQuantity = SV có quyết định kỷ luật trong khoảng thời gian
                Count(Distinct Case When tblSanction.StudentID Is Not Null Then SIM_Student.StudentID End) as WarningQuantity,
                -- SV tốt nghiệp trong khoảng thời gian (dùng cho StudyQuantity)
                Count(Distinct Case When tblGraduation.StudentID Is Not Null Then SIM_Student.StudentID End) as GraduationInPeriod,
                Sum(Case when SIM_Student.Status = 2 then 1 else 0 end) as GraduationQuantity
            From SIM_Student
            Left Join
            (
                Select Distinct
                    StudentID
                From SIM_Sanction
                Where SigningDate >= @FromDate
                    And SigningDate <= @ToDate
            ) tblSanction On tblSanction.StudentID = SIM_Student.StudentID
            Left Join
            (
                Select Distinct
                    StudentID
                From SIM_GraduationResult
                Where CreatedDate >= @FromDate
                    And CreatedDate <= @ToDate
                    And ResultReview = 1
            ) tblGraduation On tblGraduation.StudentID = SIM_Student.StudentID
            Where SIM_Student.IsDeleted = 0
            Group by SIM_Student.ClassID
        ) tblStudent on tblStudent.ClassID = SIM_Class.ClassID
    Where SIM_Class.IsActived = 1
        And SIM_Class.ClassType = 0
        And ISNULL(tblStudent.TotalStudent, 0) > 0
        And (@ClassID is null or @ClassID = N'' or CHARINDEX(',' + SIM_Class.ClassID + ',', ',' + @ClassID + ',') > 0)
        And (@ScienceID is null or @ScienceID = N'' or CHARINDEX(',' + SIM_Class.ScienceID + ',', ',' + @ScienceID + ',') > 0)
        And (@CourseID is null or @CourseID = N'' or CHARINDEX(',' + SIM_Class.CourseID + ',', ',' + @CourseID + ',') > 0);

    /* --- KPI Tổng quan --- */
    Declare @TotalStudent int;
    Declare @StudyingStudent int;
    Declare @GraduatedStudent int;
    Declare @WarningStudent int;
    Declare @TotalClass int;
    Declare @TotalScience int;
    Declare @TotalCourse int;
    Declare @GraduationRate decimal(18, 1);

    Select
        @TotalClass = COUNT(*),
        @TotalStudent = ISNULL(SUM(NowStudentCount), 0),
        @StudyingStudent = ISNULL(SUM(StudyQuantity), 0),
        @GraduatedStudent = ISNULL(SUM(GraduationQuantity), 0),
        @WarningStudent = ISNULL(SUM(WarningQuantity), 0)
    From #tblClassData;

    Select @TotalScience = COUNT(Distinct ScienceID) From #tblClassData;
    Select @TotalCourse = COUNT(Distinct CourseID) From #tblClassData;

    If (@StudyingStudent + @GraduatedStudent) > 0
        Set @GraduationRate = Round((@GraduatedStudent * 100.0) / (@StudyingStudent + @GraduatedStudent), 1);
    Else
        Set @GraduationRate = 0;

    Insert Into #tblMetrics (SectionGroup, SectionTitle, MetricKey, MetricLabel, MetricValue, MetricNote, ColorClass, SortOrder)
    Values
        (N'overview', N'Tổng quan hệ thống', N'totalStudent', N'Tổng sinh viên', Cast(@TotalStudent as nvarchar(20)), N'trong phạm vi lọc', N'blue', 101),
        (N'overview', N'Tổng quan hệ thống', N'studyingStudent', N'SV đang học', Cast(@StudyingStudent as nvarchar(20)), N'sau loại trừ KL/TN theo ngày', N'teal', 102),
        (N'overview', N'Tổng quan hệ thống', N'graduatedStudent', N'SV đã tốt nghiệp', Cast(@GraduatedStudent as nvarchar(20)), N'trạng thái tốt nghiệp', N'green', 103),
        (N'overview', N'Tổng quan hệ thống', N'totalClass', N'Tổng lớp học', Cast(@TotalClass as nvarchar(20)), N'lớp đang mở', N'teal', 104),
        (N'overview', N'Tổng quan hệ thống', N'totalScience', N'Số khoa / ngành', Cast(@TotalScience as nvarchar(20)), N'đang có lớp', N'blue', 105),
        (N'overview', N'Tổng quan hệ thống', N'totalCourse', N'Số khóa học', Cast(@TotalCourse as nvarchar(20)), N'đang có lớp', N'blue', 106),
        (N'overview', N'Tổng quan hệ thống', N'graduationRate', N'Tỷ lệ tốt nghiệp', Cast(@GraduationRate as nvarchar(20)) + N'%', N'trên SV đang học + TN', N'green', 107),
        (N'overview', N'Tổng quan hệ thống', N'warningStudent', N'SV cảnh báo / nghỉ', Cast(@WarningStudent as nvarchar(20)), N'có QĐ kỷ luật trong kỳ', N'yellow', 108);

    /* Result set 1 — KPI tổng quan */
    IF @ResultSet IS NULL OR @ResultSet = 1
    BEGIN
        Select
            SectionGroup,
            SectionTitle,
            MetricKey,
            MetricLabel,
            MetricValue,
            MetricNote,
            ColorClass,
            SortOrder
        From #tblMetrics
        Order by SortOrder;
    END

    /* Result set 2 — Cảnh báo (tái sử dụng DASH_Overview) */
    IF @ResultSet IS NULL OR @ResultSet = 2
    BEGIN
        If OBJECT_ID(N'dbo.DASH_Overview_GetData', N'P') IS NOT NULL
        Begin
            Create Table #tblAlerts
            (
                AlertCode nvarchar(50),
                AlertType nvarchar(20),
                AlertText nvarchar(500),
                AlertMeta nvarchar(200)
            );

            Insert Into #tblAlerts
            Exec dbo.DASH_Overview_GetData
                @YearID = @YearID,
                @Semester = @Semester,
                @ScienceID = @ScienceID,
                @CourseID = @CourseID,
                @ResultSet = 12;

            Select AlertCode, AlertType, AlertText, AlertMeta From #tblAlerts;
            Drop Table #tblAlerts;
        End
        Else
        Begin
            Select
                Cast(null as nvarchar(50)) as AlertCode,
                Cast(null as nvarchar(20)) as AlertType,
                Cast(null as nvarchar(500)) as AlertText,
                Cast(null as nvarchar(200)) as AlertMeta
            Where 1 = 0;
        End
    END

    Drop Table #tblMetrics;
    Drop Table #tblClassData;
END
GO

