    Exec dbo.DASH_MainSummary_GetData @ResultSet = 1;
    Exec dbo.DASH_MainSummary_GetData @FromDate = '2026-07-01', @ToDate = '2026-07-31', @ResultSet = 1;
*/

/*
    Dashboard Tổng quan — DASH_Overview_GetFilter
    Lấy danh sách Năm học / Khoa / Khóa / Lớp
    Khoa / Khóa / Lớp ủy quyền DASH_StudentClassSize_GetFilter (chuẩn Sĩ số lớp).

    @ScienceID — tuỳ chọn, lọc khóa / lớp
    @CourseID  — tuỳ chọn, lọc lớp
    @ListType  — 0 = Năm học, 1 = Khoa, 2 = Khóa, 3 = Lớp
*/

IF OBJECT_ID(N'dbo.DASH_Overview_GetFilter', N'P') IS NOT NULL
    DROP PROCEDURE dbo.DASH_Overview_GetFilter;
GO

CREATE PROCEDURE dbo.DASH_Overview_GetFilter
(
    @ScienceID nvarchar(1000) = NULL,
    @CourseID nvarchar(1000) = NULL,
    @ListType tinyint
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @ListType = 0
    BEGIN
        Select
            SIM_Year.YearID,
            SIM_Year.YearName
        From SIM_Year
        Order by SIM_Year.YearID Desc;
        RETURN;
    END

    IF @ListType = 1
    BEGIN
        Exec dbo.DASH_StudentClassSize_GetFilter
            @ScienceID = @ScienceID,
            @CourseID = @CourseID,
            @ListType = 1;
        RETURN;
    END

    IF @ListType = 2
    BEGIN
        Exec dbo.DASH_StudentClassSize_GetFilter
            @ScienceID = @ScienceID,
            @CourseID = @CourseID,
            @ListType = 2;
        RETURN;
    END

    IF @ListType = 3
    BEGIN
        Exec dbo.DASH_StudentClassSize_GetFilter
            @ScienceID = @ScienceID,
            @CourseID = @CourseID,
            @ListType = 3;
        RETURN;
    END
END
GO

/*
    Ví dụ test:
    Exec dbo.DASH_Overview_GetFilter @ListType = 0;
    Exec dbo.DASH_Overview_GetFilter @ListType = 1;
    Exec dbo.DASH_Overview_GetFilter @ListType = 2, @ScienceID = NULL;
    Exec dbo.DASH_Overview_GetFilter @ListType = 3, @ScienceID = NULL, @CourseID = NULL;
*/

