function bindEvents() {
    if (eventsBound) {
        return;
    }
    eventsBound = true;

    var loadBtn = getEl("schDashBtnLoad");
    var refreshBtn = getEl("schDashBtnRefresh");
    var fromDateEl = filterConfig.fromDate ? getEl(filterConfig.fromDate) : null;
    var toDateEl = filterConfig.toDate ? getEl(filterConfig.toDate) : null;

    if (loadBtn) {
        loadBtn.addEventListener("click", function () {
            loadDashboardData();
        });
    }

    if (refreshBtn) {
        refreshBtn.addEventListener("click", function () {
            refreshBtn.classList.add("is-loading");
            loadDashboardData();
            setTimeout(function () {
                refreshBtn.classList.remove("is-loading");
            }, 600);
        });
    }

    if (fromDateEl) {
        fromDateEl.addEventListener("change", function () {
            loadDashboardData();
        });
    }
    if (toDateEl) {
        toDateEl.addEventListener("change", function () {
            loadDashboardData();
        });
    }

    initMultiSelectDropdowns();
    readFilterConfig();
    var scienceWrap = filterConfig.scienceId ? getEl(filterConfig.scienceId) : null;
    var courseWrap = filterConfig.courseId ? getEl(filterConfig.courseId) : null;
    var classWrap = filterConfig.classId ? getEl(filterConfig.classId) : null;
    if (scienceWrap) {
        updateMultiSelectCount(scienceWrap);
    }
